function role(){return roles[state.role]}
function label(key){const n=N[key];return n?T(n[0],n[1]):key}
function button(txt,action,cls='primary',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${txt}</button>`}
function goButton(key){if(key==='students'&&state.role==='rector')key='analytics';return `<a class="text-link" href="#${state.role}/${key}">${T('Барлығы','Все')} ${icon('arrow')}</a>`}
function card(title,body,action='',cls=''){return `<section class="card ${cls}">${title?`<div class="card-header"><h2>${title}</h2>${action}</div>`:''}${body}</section>`}
function avatar(init){return `<span class="avatar">${esc(init)}</span>`}
function kpi(title,value,caption,ic='chart',accent=false){return `<div class="kpi"><div class="kpi-top"><span>${title}</span>${icon(ic)}</div><div class="kpi-value ${accent?'accent':''}">${value}</div><div class="kpi-bottom">${caption}</div></div>`}
function bar(name,value,cap=''){return `<div class="progress-item"><div class="row"><span>${name}</span><b>${value}${cap}</b></div><div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,Number(value)))}%"></div></div></div>`}
function score(n){return `<span class="score ${n>=75?'good':''}">${Number(n).toFixed(1)}</span>`}
function points(){return 1240+state.events.reduce((a,id)=>a+(events.find(e=>e.id===id)?.points||0)*10,0)}
function igpa(){return 34+state.events.reduce((a,id)=>a+(events.find(e=>e.id===id)?.points||0),0)}
function tabs(options,current,action){return `<div class="tabs" role="group">${options.map(([value,name])=>`<button class="${current===value?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${current===value}">${name}</button>`).join('')}</div>`}
function navigate(page){if(state.page===page){render();return}location.hash=`${state.role}/${page}`}
function updateRoute(){const [r,p]=location.hash.slice(1).split('/');if(roles[r])state.role=r;const valid=['home',...role().nav,...role().extra];state.page=valid.includes(p)?p:'home';state.filter='all';state.period='today';state.query='';persist();render();window.scrollTo(0,0)}
function shell(content){
 const r=role(), primary=state.role==='student'?['home','schedule','grades','tasks']:r.nav.filter(x=>!['more','ai'].includes(x));
 const extra=state.role==='student'?['chats','events','points','jobs','support']:r.extra.filter(x=>!primary.includes(x));
 return `<aside class="sidebar"><a class="brand" href="#${state.role}/home" aria-label="N&D">${logo()}</a><button class="workspace-switch" data-action="about"><span class="workspace-emblem">${icon('cap')}</span><span><b>${T('Менің университетім','Мой университет')}</b><small>${'2026–2027'}</small></span>${icon('chevron')}</button><div class="workspace-label">${T('Жұмыс кеңістігі','Рабочее пространство')}</div><nav class="side-nav" aria-label="${T('Негізгі мәзір','Основное меню')}">${primary.map(navItem).join('')}</nav>${extra.length?`<div class="workspace-label section-label">${state.role==='student'?T('Кампус','Кампус'):T('Құралдар','Инструменты')}</div><nav class="side-nav" aria-label="${T('Қосымша бөлімдер','Дополнительные разделы')}">${extra.map(navItem).join('')}</nav>`:''}<div class="side-bottom"><a class="nav-link ai-nav ${state.page==='ai'?'active':''}" href="#${state.role}/ai">${icon('spark')}<span>${label('ai')}</span><span class="beta-tag">DEMO</span></a><div class="access-note">${icon('lock')}<span>${T(...r.scope)}</span></div><div class="account">${avatar(r.initials)}<div><b>${r.person}</b><small>${T(...r.name)}</small></div><button class="icon-btn" data-action="about" aria-label="${T('Демо туралы','О демоверсии')}">${icon('more')}</button></div></div></aside><div class="shell"><header class="topbar"><a class="mobile-brand" href="#${state.role}/home" aria-label="N&D">${logo()}</a><div class="breadcrumb"><span>${T(...r.name)}</span><span class="slash">/</span><strong>${label(state.page)}</strong></div><div class="top-actions"><button class="search-trigger" data-action="command" aria-label="${T('Бөлімді іздеу','Найти раздел')}">${icon('search')}<span>${T('Бөлімді іздеу','Найти раздел')}</span><kbd>Ctrl K</kbd></button><div class="top-divider"></div><select class="role-switch" id="role-select" aria-label="${T('Демо рөлін таңдау','Выбрать демо-роль')}">${Object.entries(roles).map(([key,r])=>`<option value="${key}" ${key===state.role?'selected':''}>${T(...r.name)}</option>`).join('')}</select><div class="language" aria-label="Language"><button data-action="lang" data-value="kk" class="${state.lang==='kk'?'active':''}">Қаз</button><button data-action="lang" data-value="ru" class="${state.lang==='ru'?'active':''}">Рус</button></div><button class="icon-btn theme-btn" data-action="theme" aria-label="${T('Тақырыпты ауыстыру','Переключить тему')}">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="notifications" aria-label="${T('Хабарландырулар','Уведомления')}">${icon('bell')}<i class="notification-dot"></i></button><button type="button" class="icon-btn" id="nd-logout" title="${T('Шығу','Выйти')}" aria-label="${T('Аккаунттан шығу','Выйти из аккаунта')}">${icon('logout')}</button><span class="top-avatar">${avatar(r.initials)}</span></div></header><main id="main" tabindex="-1"><div class="page-enter">${hero()}${content}</div><footer class="footer"><span>N&D <span class="footer-dot">/</span> ${T('Университет порталы','Университетский портал')}</span><button data-action="about">${T('Демо · үлгі деректер','Демо · пример данных')} ${icon('help')}</button></footer></main></div><nav class="bottom-nav" aria-label="${T('Төменгі мәзір','Нижнее меню')}">${r.nav.map(k=>`<a href="#${state.role}/${k}" class="${state.page===k?'active':''}">${icon(N[k][2])}<span>${label(k)}</span></a>`).join('')}</nav>`;
}
function hero(){
 let title=label(state.page),sub=T(...role().scope);
 const student=state.role==='student',date=new Intl.DateTimeFormat(state.lang==='kk'?'kk-KZ':'ru-RU',{day:'numeric',month:'long',timeZone:'Asia/Qyzylorda'}).format(new Date());
 if(state.page==='home'){title=student?T('Қайырлы күн, Айсана','Добрый день, Айсана'):T('Жұмыс кеңістігі','Рабочее пространство');sub=student?T('3 курс · ИС-31 · Ақпараттық жүйелер','3 курс · ИС-31 · Информационные системы'):T(...role().scope)+' · '+T('Ағымдағы семестр','Текущий семестр');}
 return `<div class="hero"><div><h1>${title}</h1><p>${sub}</p></div><div class="hero-right">${state.page==='home'?`<span class="date-label">${icon('calendar')}${date}</span>`:`<span class="scope-label">${icon('lock')}${T(...role().name)}</span>`}<button class="demo-label" data-action="about">${T('Демо нұсқа','Демоверсия')}</button></div></div>`;
}
function studentHome(){
 const todayRows=scheduleRows();
 const scheduleBody=state.period==='week'?`<div class="compact-week">${[T('Дс','Пн'),T('Сс','Вт'),T('Ср','Ср'),T('Бс','Чт'),T('Жм','Пт')].map((d,i)=>`<div><span class="week-name">${d}</span>${todayRows.slice(i%2,i%2+2).map(s=>`<div class="week-lesson"><time>${s[0]}</time><b>${s[2]}</b><small>${s[3].split(' · ')[0]}</small></div>`).join('')}</div>`).join('')}</div>`:todayRows.map((s,i)=>`<div class="agenda-item ${i===0?'agenda-next':''}"><div class="agenda-time"><time>${s[0]}</time><span>${s[1]}</span></div><div class="agenda-track"><i></i></div><div class="agenda-content"><div class="row"><h3>${s[2]}</h3>${i===0?`<span class="pill rose">${T('Келесі сабақ','Следующая пара')}</span>`:''}</div><p>${s[3]}</p></div><a class="agenda-arrow" href="#student/schedule" aria-label="${T('Кестені ашу','Открыть расписание')}">${icon('chevron')}</a></div>`).join('');
 const upcoming=events.slice(0,2).map(e=>`<a class="campus-event" href="#student/events"><span class="event-date"><b>${e.day}</b><small>${T(...e.month)}</small></span><span><b>${T(...e.name)}</b><small>${T(...e.place)}</small></span>${icon('chevron')}</a>`).join('');
 return `<div class="kpis overview-metrics">${kpi(T('Орташа балл','Средний балл'),'72.4',T('5 семестр · 100 балдық жүйе','5 семестр · по 100-балльной шкале'),'book',true)}${kpi(T('Қатысу','Посещаемость'),'95%',T('Осы семестрдегі сабақтар','Занятия в этом семестре'),'check')}${kpi(T('Белсенділік IGPA','Активность IGPA'),String(igpa()),T('Университет өміріне қатысу','Участие в жизни университета'),'award')}</div><div class="home-grid"><div class="home-primary"><section class="card schedule-panel"><div class="card-header"><div><h2>${T('Сабақтар','Занятия')}</h2><p class="subline">${T('Бүгінгі күнді жоспарлаңыз','Всё для планирования дня')}</p></div>${tabs([['today',T('Бүгін','Сегодня')],['week',T('Апта','Неделя')]],state.period,'period')}</div><div class="agenda">${scheduleBody}</div><a class="panel-bottom-link" href="#student/schedule">${T('Толық кестені ашу','Открыть полное расписание')}${icon('arrow')}</a></section><section class="card performance-panel"><div class="card-header"><div><h2>${T('Пәндер бойынша үлгерім','Успеваемость по дисциплинам')}</h2><p class="subline">${T('Ағымдағы семестр нәтижелері','Результаты текущего семестра')}</p></div><a class="text-link" href="#student/grades">${T('Барлық бағалар','Все оценки')}${icon('arrow')}</a></div><div class="grade-preview">${studentSubjects.map(s=>`<div class="grade-preview-row"><div><b>${T(s[0],s[1])}</b><span>${s[2]<70?T('Назар аударыңыз','Стоит уделить внимание'):T('Ағымдағы нәтиже','Текущий результат')}</span></div><div class="grade-meter"><i style="width:${s[2]}%"></i></div><strong>${s[2]}<small>/ 100</small></strong></div>`).join('')}</div></section>${assistantShortcut()}</div><aside class="home-secondary"><section class="side-section tasks-panel"><div class="card-header"><h2>${T('Тапсырмалар','Задания')}</h2><span class="counter">${2-state.submitted.filter(x=>['db','algo'].includes(x)).length}</span></div>${taskRows()}<a class="subtle-link" href="#student/tasks">${T('Барлық тапсырмалар','Все задания')}${icon('arrow')}</a></section><section class="side-section"><div class="card-header"><h2>${T('Кампуста','В кампусе')}</h2><a class="icon-btn" href="#student/events" aria-label="${T('Іс-шаралар','Мероприятия')}">${icon('arrow')}</a></div>${upcoming}</section><section class="points-compact"><div class="row"><span>${icon('award')}${T('Менің поинттерім','Мои поинты')}</span><a href="#student/points" aria-label="${T('Ұпайларды ашу','Открыть поинты')}">${icon('arrow')}</a></div><strong>${points().toLocaleString('ru')}</strong><p>${Math.max(0,1500-points())} ${T('поинт — «Алтын» деңгейіне дейін','поинтов до уровня «Золото»')}</p><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,points()/1500*100)}%"></div></div></section></aside></div>`;
}
function scheduleRows(){if(state.role==='teacher')return [['09:00','10:20',T('Алгоритмдер · ИС-31','Алгоритмы · ИС-31'),T('204 ауд. · Дәріс','Ауд. 204 · Лекция')],['10:30','11:50',T('Алгоритмдер · ИС-32','Алгоритмы · ИС-32'),T('204 ауд. · Практика','Ауд. 204 · Практика')]];return [['09:00','10:20',T('Алгоритмдер','Алгоритмы'),T('204 ауд. · Дәріс · Асель Н.','Ауд. 204 · Лекция · Асель Н.')],['10:30','11:50',T('Дерекқор','Базы данных'),T('311 ауд. · Практика · Марат К.','Ауд. 311 · Практика · Марат К.')],['12:00','13:20',T('Ағылшын тілі','Английский язык'),T('105 ауд. · Семинар · Дана Т.','Ауд. 105 · Семинар · Дана Т.')]]}
function scheduleRow(s,i=0){return `<div class="schedule-item"><div class="schedule-time">${s[0]}<small>${s[1]}</small></div><div><h3>${s[2]}</h3><p>${s[3]}</p></div><span class="end pill">${T('ИС-31','ИС-31')}</span></div>`}
function schedule(){return `<div class="toolbar">${tabs([['today',T('Бүгін','Сегодня')],['week',T('Апта','Неделя')]],state.period,'period')}<span class="muted" style="font-size:12px">${T('2–6 қараша 2026','2–6 ноября 2026')}</span>${button(icon('download')+' '+T('Жүктеу','Скачать'),'schedule-export','small')}</div>${card('',state.period==='week'?`<div class="week-grid">${[T('Дүйсенбі','Понедельник'),T('Сейсенбі','Вторник'),T('Сәрсенбі','Среда'),T('Бейсенбі','Четверг'),T('Жұма','Пятница')].map((day,i)=>`<div class="week-day"><h3>${day}, ${i+2}</h3>${scheduleRows().slice(i%2,i%2+2).map(s=>`<div class="week-lesson"><span class="muted">${s[0]}</span><b>${s[2]}</b><small>${s[3]}</small></div>`).join('')}</div>`).join('')}</div>`:`<h2>${T('Бейсенбі, 5 қараша','Четверг, 5 ноября')}</h2><div class="section-gap">${scheduleRows().map(scheduleRow).join('')}</div>`)}<p class="notice section-gap">${icon('lock')}${T('Тек өз тобыңыздың сабақтары көрсетіледі','Показаны занятия только вашей группы')}</p>`}
function taskRows(){return [{id:'db',name:T('Дерекқор зертханасы №3','Лабораторная по базам данных №3'),sub:T('Жұмаға дейін · Марат К.','До пятницы · Марат К.')},{id:'algo',name:T('Алгоритмдер: сұрыптау','Алгоритмы: сортировка'),sub:T('9 қарашаға дейін · Асель Н.','До 9 ноября · Асель Н.')}].map(a=>`<div class="list-row"><span class="task-icon">${icon(state.submitted.includes(a.id)?'check':'file')}</span><div class="grow"><b>${a.name}</b><small>${a.sub}</small></div>${state.submitted.includes(a.id)?`<span class="pill green">${T('Тапсырылды','Сдано')}</span>`:button(T('Ашу','Открыть'),'task','small',`data-id="${a.id}"`)}</div>`).join('')}
function tasks(){if(state.role==='teacher')return card(T('Тексеруге арналған жұмыстар','Работы на проверку'),`<p class="subline">${T('Алгоритмдер · №3 зертханалық жұмыс','Алгоритмы · Лабораторная №3')}</p>${students.slice(0,4).map((x,i)=>`<div class="list-row"><div class="grow"><b>${x.name}</b><small>${T('ИС-31 тобы','Группа ИС-31')}</small></div>${i===2?`<span class="pill yellow">${T('Тапсырылмаған','Не сдано')}</span>`:`<a class="btn small" href="#teacher/journal">${T('Бағалау','Оценить')}</a>`}</div>`).join('')}`);return card(T('Менің тапсырмаларым','Мои задания'),taskRows()+`<p class="notice section-gap">${icon('file')}${T('Демо нұсқада тапсырғаныңыз осы браузерде сақталады.','В демоверсии отметка о сдаче сохраняется в этом браузере.')}</p>`)}
function grades(){return `<div class="grid dashboard"><div class="stack">${card(T('Пәндер бойынша нәтижелер','Результаты по дисциплинам'),studentSubjects.map(s=>bar(T(s[0],s[1]),s[2])).join('')+`<div class="row section-gap"><span class="muted">${T('Семестрдің орташа балы','Средний балл за семестр')}</span><strong style="font-size:28px;color:var(--acc)">72.4</strong></div>`)}${card(T('Соңғы нәтижелер','Последние результаты'),`<div class="list-row"><div class="grow"><b>${T('Алгоритмдер · Зертханалық жұмыс','Алгоритмы · Лабораторная работа')}</b><small>03.11.2026</small></div>${score(85)}</div><div class="list-row"><div class="grow"><b>${T('Дерекқор · Аралық бақылау','Базы данных · Рубежный контроль')}</b><small>02.11.2026</small></div>${score(65)}</div>`)}</div><div class="stack">${card(T('Қатысу','Посещаемость'),`<div class="kpi-value accent">95%</div><p class="muted">${T('Айына 2 сабақ жіберілді','2 пропуска за месяц')}</p>${bar(T('Сабаққа қатысу','Посещение занятий'),95,'%')}`)}${card(T('Келесі қадам','Следующий шаг'),`<p class="muted">${T('Дерекқор бойынша қателерді оқытушымен талдауды ұсынамыз.','Предлагаем разобрать ошибки по базам данных с преподавателем.')}</p><a class="btn primary" href="#student/chats">${T('Оқытушыға жазу','Написать преподавателю')} ${icon('arrow')}</a>`)}</div></div>`}
function eventPage(){
 const own=state.filter==='mine',arr=events.filter(e=>!own||state.events.includes(e.id));
 return `<div class="toolbar">${tabs([['all',T('Барлық іс-шаралар','Все мероприятия')],['mine',T('Менің жазылуларым','Мои регистрации')]],state.filter,'filter')}</div><div class="events-list">${arr.map(e=>`<section class="event-list-item"><div class="event-calendar"><small>${T(...e.month)}</small><b>${e.day}</b></div><div class="event-info"><span class="event-category">${e.id==='hack'?T('Білім және технология','Образование и технологии'):e.id==='volunteer'?T('Волонтерлік','Волонтёрство'):T('Кампус өмірі','Жизнь кампуса')}</span><h2>${T(...e.name)}</h2><p>${icon('pin')}${T(...e.place)}<span>·</span>${T(...e.date)}</p></div><span class="pill rose">+${e.points} IGPA</span>${button(state.events.includes(e.id)?icon('check')+' '+T('Жазылдыңыз','Вы записаны'):T('Жазылу','Записаться'),'event',state.events.includes(e.id)?'':'primary',`data-id="${e.id}"`)}</section>`).join('')||`<div class="empty">${icon('calendar')}<h3>${T('Әзірге жазылу жоқ','Пока нет регистраций')}</h3><p>${T('Іс-шара таңдап, кампус өміріне қосылыңыз','Выберите мероприятие и присоединяйтесь к жизни кампуса')}</p></div>`}</div>`;
}
function pointPage(){return `<div class="grid two">${card(T('Менің поинттерім','Мои поинты'),`<div class="point-big">${points().toLocaleString('ru')}</div>${bar(T('Келесі деңгей: Алтын','Следующий уровень: Золото'),Math.min(100,Math.round(points()/1500*100)),'%')}<p class="muted">${Math.max(0,1500-points())} ${T('поинт қалды','поинтов осталось')}</p><a class="btn primary" href="#student/jobs">${T('Мүмкіндіктерді қарау','Посмотреть возможности')} ${icon('arrow')}</a>`)}${card(T('Ұпайлар қалай жиналады?','Как начисляются поинты?'),`<div class="list-row"><span class="task-icon">${icon('book')}</span><div class="grow"><b>${T('Оқу көрсеткіші','Учебные результаты')}</b><small>${T('Орташа балл: 72.4 / 100','Средний балл: 72.4 / 100')}</small></div><b>+620</b></div><div class="list-row"><span class="task-icon">${icon('award')}</span><div class="grow"><b>${T('Белсенділік','Активность')} (IGPA)</b><small>${T('Жиналған IGPA','Накоплено IGPA')}: ${igpa()}</small></div><b>+${420+(points()-1240)}</b></div><div class="list-row"><span class="task-icon">${icon('check')}</span><div class="grow"><b>${T('Қатысу','Посещаемость')}</b><small>95%</small></div><b>+200</b></div><p class="notice section-gap">${icon('help')}${T('Демода іс-шараға жазылу IGPA мен поинттерді бірден қосады. Жұмыс нұсқасында қатысуды растау қажет.','В демо запись на мероприятие сразу добавляет IGPA и поинты. В рабочей версии потребуется подтверждение участия.')}</p>`)}</div>`}
function jobs(){const jobs=[['lab',T('Зертхана көмекшісі','Помощник лаборатории'),500,'IT',T('Зертхана жұмысын ұйымдастыруға көмек','Помощь в организации работы лаборатории')],['admissions',T('Қабылдау комиссиясы','Приёмная комиссия'),800,'N&D',T('Талапкерлерге бағыт беру','Консультирование абитуриентов')],['smm',T('Университет SMM','SMM университета'),1000,'SMM',T('Университет өмірі туралы контент','Контент о жизни университета')],['intern',T('Серіктестегі тәжірибе','Стажировка у партнёра'),1500,'DEV',T('Бағдарламалау бойынша тәжірибе','Практика в разработке')]];return `<div class="notice">${icon('award')}${T('Сізде','У вас')} ${points().toLocaleString('ru')} ${T('поинт. Демо өтінімдер осы браузерде сақталады.','поинтов. Демо-заявки сохраняются в этом браузере.')}</div><div class="grid two">${jobs.map(([id,name,min,logo,desc])=>`<section class="card job-card"><div class="job-top"><div class="job-logo">${logo}</div><div><h2>${name}</h2><span class="subline">${T('Университет мүмкіндіктері','Возможности университета')}</span></div></div><p>${desc}</p><div class="row"><span class="pill ${points()>=min?'green':''}">${min} ${T('поинттен','поинтов')}</span><span class="locked-note">${points()<min?icon('lock')+' '+(min-points())+' '+T('поинт жетіспейді','поинтов не хватает'):T('Қолжетімді','Доступно')}</span></div>${button(state.applications.includes(id)?icon('check')+' '+T('Өтінім сақталды','Заявка сохранена'):T('Өтінім беру','Откликнуться'),'job',points()>=min?'primary':'',`data-id="${id}" ${points()<min||state.applications.includes(id)?'disabled':''}`)}</section>`).join('')}</div>`}
function support(){return `<div class="notice">${icon('lock')}${T('Жазылу ақпараты басқа рөлдердің демо экрандарына берілмейді.','Информация о записи не передаётся в демо-экраны других ролей.')}</div><div class="grid two">${[['wellbeing','heart',T('Психологиялық қолдау','Психологическая поддержка'),T('Маманмен сөйлесуге ыңғайлы уақыт таңдаңыз.','Выберите удобное время для беседы со специалистом.')],['career','briefcase',T('Кәсіби бағдар маманы','Карьерный консультант'),T('Мансап бағыты, тәжірибе және резюме туралы кеңес.','Консультация по карьере, стажировкам и резюме.')]].map(([id,ic,name,desc])=>`<section class="card support-card">${icon(ic)}<h2>${name}</h2><p>${desc}</p>${['15:00','11:00'].map((time,i)=>button((i===0?T('Бс','Чт'):T('Жм','Пт'))+' '+time,'book','small',`data-id="${id}-${time}"`)).join(' ')}${state.bookings.filter(x=>x.startsWith(id)).map(x=>`<div class="booked">${icon('check')} ${T('Демо жазылу сақталды','Демо-запись сохранена')}: ${x.endsWith('15:00')?T('Бс, 15:00','Чт, 15:00'):T('Жм, 11:00','Пт, 11:00')}</div>`).join('')}</section>`).join('')}</div><p class="notice section-gap">${icon('help')}${T('Бұл демонстрация. Нақты маманға жазылмайды және хабарлама жіберілмейді.','Это демонстрация. Запись к реальному специалисту и отправка уведомлений не выполняются.')}</p>`}
function staffHome(){
 if(state.role==='teacher')return teacherHome();
 const rector=state.role==='rector',dean=state.role==='dean',curator=state.role==='curator',mean=rector?'70.8':dean?'74.1':'72.4',att=rector?'93%':dean?'96%':'95%',count=rector?'4 120':dean?'1 048':'24',numbers=rector?[1150,1040,960,970]:[312,288,251,197],total=numbers.reduce((a,b)=>a+b,0);
 const rows=curator?students.slice(0,4).map(studentListRow).join(''):`<div class="course-table">${numbers.map((n,i)=>`<a href="#${state.role}/${rector?'analytics':'students'}"><span class="course-number">0${i+1}</span><span>${i+1} ${T('курс','курс')}</span><div class="course-bar"><i style="width:${n/Math.max(...numbers)*100}%"></i></div><b>${n.toLocaleString('ru')}</b><small>${Math.round(n/total*100)}%</small>${icon('chevron')}</a>`).join('')}</div>`;
 return `<div class="kpis overview-metrics">${kpi(T('Студенттер','Студенты'),count,T(...role().scope),'users')}${kpi(T('Орташа балл','Средний балл'),mean,T('100 балдық жүйе','По 100-балльной шкале'),'book',true)}${kpi(T('Қатысу','Посещаемость'),att,T('Ағымдағы семестр','Текущий семестр'),'check')}</div><div class="home-grid"><div class="home-primary"><section class="card trend-panel"><div class="card-header"><div><h2>${T('Қатысу динамикасы','Динамика посещаемости')}</h2><p class="subline">${T('Апта бойынша шолу','Обзор по дням недели')}</p></div><span class="chart-key"><i></i>${T('Қатысу','Посещаемость')}</span></div>${overviewTrend()}</section>${card(curator?T('Менің студенттерім','Мои студенты'):T('Студенттер бойынша шолу','Обзор студентов'),rows,goButton('students'),'course-panel')}${assistantShortcut()}</div><aside class="home-secondary"><section class="side-section"><div class="card-header"><h2>${T('Назар аудару','Требует внимания')}</h2><span class="status-dot"></span></div><div class="attention-item"><span class="attention-value">${rector?86:dean?41:5}</span><div><b>${T('Академиялық қарыздар','Академические задолженности')}</b><p>${T('Студенттермен жеке жұмыс','Индивидуальная работа со студентами')}</p></div></div><div class="attention-item"><span class="attention-value">${dean?6:3}</span><div><b>${T('Жауап күтуде','Ожидают ответа')}</b><p>${T('Ашық сұраулар','Открытые обращения')}</p></div></div>${button(T('Толығырақ қарау','Посмотреть подробнее')+' '+icon('arrow'),dean?'reminders':'show-risks','block')}</section><section class="side-section"><div class="card-header"><h2>${T('Пәндер бойынша','По дисциплинам')}</h2></div>${[['Алгоритмдер','Алгоритмы',74.5],['Дерекқор','Базы данных',65.2],['Ағылшын тілі','Английский язык',67.1]].map(x=>bar(T(x[0],x[1]),x[2])).join('')}</section><section class="side-section quick-actions"><div class="card-header"><h2>${T('Жылдам әрекеттер','Быстрые действия')}</h2></div><a href="#${state.role}/${rector?'finance':dean?'curators':'chats'}">${icon(rector?'wallet':dean?'users':'chat')}<span>${rector?T('Қаржы есебі','Финансовый отчёт'):dean?T('Кураторлар мен топтар','Кураторы и группы'):T('Топ чаты','Чат группы')}</span>${icon('chevron')}</a><button data-action="export">${icon('download')}<span>${T('Есепті жүктеу','Скачать отчёт')}</span>${icon('chevron')}</button></section></aside></div>`;
}
function chart(values,names){return `<div class="chart-bars" role="img" aria-label="${T('Көрсеткіштер диаграммасы','Диаграмма показателей')}">${values.map((n,i)=>`<div class="chart-column"><strong>${n}</strong><div class="bar" style="--height:${Math.max(5,n/Math.max(...values)*110)}px"></div><small>${names[i]}</small></div>`).join('')}</div><p class="chart-legend"><span class="dot"></span>${T('Демонстрациялық деректер','Демонстрационные данные')}</p>`}
function analytics(){const year=state.period==='year',dean=state.role==='dean';return `<div class="toolbar">${tabs([['today',T('Кесінді','Срез')],['year',T('Жыл','Год')]],state.period,'period')}<span class="muted" style="font-size:12px">${year?'2026–2027':T('1 тамыз – 5 қараша 2026','1 августа – 5 ноября 2026')}</span>${button(icon('download')+' '+T('Есеп','Отчёт'),'export','small')}</div><div class="kpis">${kpi(T('Орташа балл','Средний балл'),year?'73.2':dean?'74.1':'70.8',T('Алдыңғы кезеңмен салыстыру','Сравнение с предыдущим периодом'),'book',true)}${kpi(T('Қатысу','Посещаемость'),year?'94.1%':dean?'96%':'93.4%',T('Белгіленген сабақтар бойынша','По отмеченным занятиям'),'check')}${kpi(T('Журнал толуы','Заполнение журнала'),year?'91.4%':'88.2%',T('Тақырыбы мен бағасы бар сабақтар','Занятия с темой и оценками'),'file')}</div><div class="grid two">${card(T('Пәндер бойынша','По дисциплинам'),[['Алгоритмдер','Алгоритмы',year?76.4:74.5],['Дерекқор','Базы данных',year?69.2:65.2],['Ағылшын тілі','Английский язык',year?71.8:67.1],['Математика','Математика',year?68.1:63.6]].map(x=>bar(T(x[0],x[1]),x[2])).join(''))}${card(T('Курстар бойынша орташа балл','Средний балл по курсам'),chart(year?[74,75,77,80]:[71.2,72.8,75.6,78.4],[1,2,3,4].map(n=>n+' '+T('курс','курс'))))}</div>`}
function performance(){const arr=[71.2,72.8,75.6,78.4];return `<div class="toolbar">${tabs([['all',T('Барлығы','Все')],...[1,2,3,4].map(n=>[String(n),n+' '+T('курс','курс')])],state.filter,'filter')}</div><div class="grid two">${arr.map((n,i)=>state.filter==='all'||Number(state.filter)===i+1?card((i+1)+' '+T('курс','курс'),`<div class="row"><div><div class="kpi-value accent">${n}</div><small class="muted">${T('Орташа балл','Средний балл')}</small></div><span class="pill ${i===1?'yellow':'green'}">${i===1?'−0.9':i===0?'+1.4':i===2?'+2.1':'+0.5'}</span></div><div class="section-gap">${bar(T('Қатысу','Посещаемость'),[94,93,96,98][i],'%')}</div>`):'').join('')}</div><div class="grid two section-gap">${card(T('Назар аудару','Требует внимания'),`<div class="row"><span>${T('Қарызы бар студенттер','Студенты с задолженностями')}</span><b class="score">41</b></div><p class="muted">${T('ИС-21 · орташа балл 68.0','ИС-21 · средний балл 68.0')}</p><a class="btn" href="#dean/students">${T('Студенттерді ашу','Открыть студентов')}</a>`)}${card(T('Үздік нәтижелер','Лучшие результаты'),`<div class="kpi-value accent">124</div><p class="muted">${T('Факультеттің үздік 10%-ындағы студенттер','Студенты в лучших 10% факультета')}</p>`)}</div>`}
function studentListRow(s){return `<div class="list-row"><div class="grow person">${avatar(s.init)}<div><b>${s.name}</b><small>${s.group} · ${s.course} ${T('курс','курс')}</small></div></div>${score(s.score)}<button class="icon-btn" data-action="student" data-id="${s.id}" aria-label="${T('Карточканы ашу','Открыть карточку')} ${esc(s.name)}">${icon('chevron')}</button></div>`}
function filteredStudents(){return students.filter(s=>(state.role!=='curator'||s.group==='ИС-31')&&(state.filter==='all'||state.filter==='risk'&&s.score<65||state.filter==='debt'&&s.debt>0||Number(state.filter)===s.course)&&(!state.query||s.name.toLowerCase().includes(state.query.toLowerCase())||s.group.toLowerCase().includes(state.query.toLowerCase())))}
function studentTableBody(){const list=filteredStudents();return list.length?list.map(s=>`<tr><td><div class="person">${avatar(s.init)}<div><b>${s.name}</b><small>${s.course} ${T('курс','курс')}</small></div></div></td><td>${s.group}</td><td>${score(s.score)}</td><td>${s.att}%</td><td>${s.debt?`<span class="pill yellow">${s.debt}</span>`:'—'}</td><td><button class="icon-btn" data-action="student" data-id="${s.id}" aria-label="${T('Студент карточкасы','Карточка студента')} ${s.name}">${icon('chevron')}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${T('Студент табылмады','Студенты не найдены')}</div></td></tr>`}
function studentsPage(){return `<div class="toolbar"><input class="search" id="student-search" placeholder="${T('Аты немесе тобы бойынша іздеу…','Поиск по имени или группе…')}" value="${esc(state.query)}" aria-label="${T('Студентті іздеу','Найти студента')}">${tabs([['all',T('Барлығы','Все')],['risk',T('Қауіп','Риск')],['debt',T('Қарыз','Задолженности')]],state.filter,'filter')}${state.role!=='curator'?`<select id="course-filter" class="filter-select" aria-label="${T('Курс бойынша сүзу','Фильтр по курсу')}"><option value="all">${T('Барлық курстар','Все курсы')}</option>${[1,2,3,4].map(n=>`<option value="${n}" ${state.filter===String(n)?'selected':''}>${n} ${T('курс','курс')}</option>`).join('')}</select>`:''}${button(icon('download')+' CSV','export','small')}</div><section class="card table-card"><div class="data-table-wrap"><table class="data-table"><thead><tr>${[T('Студент','Студент'),T('Топ','Группа'),T('Орташа балл','Средний балл'),T('Қатысу','Посещаемость'),T('Қарыз','Задолженности'),''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody id="students-body">${studentTableBody()}</tbody></table></div></section><p class="notice section-gap">${icon('lock')}${T(...role().scope)} · ${T('Көрсетілген деректер — демо үлгі','Показанные данные — демонстрационный пример')}</p>`}
function curators(){const arr=[['Жанар К.','ИС-31',72.4,0],['Ерлан Т.','ИС-21',68,4],['Мадина С.','ИС-11',75.6,0],['Айдос Б.','ИС-41',79.2,2],...(state.groups||[])];return `<div class="toolbar">${button(icon('plus')+' '+T('Топ қосу','Добавить группу'),'add-group')}${button(icon('bell')+' '+T('Еске салу','Напомнить'),'reminders','')}</div><div class="grid two">${arr.map(([name,group,n,unread])=>card(esc(group),`<div class="person">${avatar(name.slice(0,2))}<div><b>${esc(name)}</b><small class="muted">${T('Топ кураторы','Куратор группы')}</small></div></div><div class="row section-gap"><span class="muted">${T('Орташа балл','Средний балл')}</span>${score(n)}</div><div class="list-row"><div class="grow"><b>${T('Жауапсыз сұраулар','Обращения без ответа')}</b></div><span class="pill ${unread?'yellow':'green'}">${unread}</span></div>${unread?button(T('Еске салу','Напомнить'),'reminder-one','small',`data-name="${esc(name)}"`):''}`)).join('')}</div>`}
function finance(){return `<div class="toolbar"><span class="pill">2026–2027 ${T('оқу жылы','учебный год')}</span>${button(icon('download')+' '+T('Есепті жүктеу','Скачать отчёт'),'export','small')}</div><div class="kpis">${kpi(T('Кіріс','Доходы'),T('4.2 млрд ₸','4,2 млрд ₸'),T('Оқу жылының көрсеткіші','Показатель учебного года'),'wallet',true)}${kpi(T('Шығыс','Расходы'),T('3.7 млрд ₸','3,7 млрд ₸'),T('Операциялық шығындар','Операционные расходы'),'wallet')}${kpi(T('Төлем жиналымы','Собираемость платежей'),'91%',T('Жоспарға қатысты','Относительно плана'),'chart')}</div><div class="grid two">${card(T('Факультеттер бойынша төлем','Платежи по факультетам'),[['ИТ','ИТ',94],['Экономика','Экономика',92],['Құқық','Право',89],['Педагогика','Педагогика',87]].map(x=>bar(T(x[0],x[1]),x[2],'%')).join(''))}${card(T('Студенттер бойынша','По студентам'),`<div class="list-row"><div class="grow"><b>${T('Қарызы бар студенттер','Студенты с задолженностью по оплате')}</b></div><strong>312</strong></div><div class="list-row"><div class="grow"><b>${T('Грантта оқиды','Обучаются по гранту')}</b></div><strong>1 480</strong></div><p class="notice section-gap">${icon('lock')}${T('Қаржы бөлімі тек ректордың демо рөлінде қолжетімді.','Финансовый раздел доступен только в демо-роли ректора.')}</p>`)}</div>`}
function ranking(){const rector=state.role==='rector';const arr=rector?[[T('ИТ факультеті','Факультет ИТ'),74.1],[T('Экономика','Экономика'),71.3],[T('Құқық','Право'),69.5],[T('Педагогика','Педагогика'),68.2]]:students.slice(0,4).sort((a,b)=>state.filter==='attendance'?b.att-a.att:b.score-a.score).map(x=>[x.name,state.filter==='attendance'?x.att:x.score]);return `${rector?`<div class="notice">${icon('help')}${T('Ішкі демо рейтинг. Нақты университет рейтингі емес.','Внутренний демо-рейтинг. Не является рейтингом реальных университетов.')}</div>`:`<div class="toolbar">${tabs([['all',T('Орташа балл','Средний балл')],['attendance',T('Қатысу','Посещаемость')]],state.filter,'filter')}</div>`}${card(rector?T('Факультеттер рейтингі','Рейтинг факультетов'):T('ИС-31 тобының рейтингі','Рейтинг группы ИС-31'),arr.map(([n,v],i)=>`<div class="list-row"><span class="task-icon" style="color:${i===0?'var(--acc)':'var(--mut)'}">${i+1}</span><div class="grow"><b>${n}</b></div>${score(v)}</div>`).join(''))}`}
function transfers(){return `<div class="toolbar">${tabs([['today',T('Апта','Неделя')],['month',T('Ай','Месяц')],['year',T('Оқу жылы','Учебный год')]],state.period,'period')}</div><div class="kpis">${kpi(T('Барлығы','Всего'),state.period==='year'?'177':state.period==='month'?'28':'7',T('Ауыстырулар','Переводы'),'swap',true)}${kpi(T('Деңгей жоғарылады','Уровень повышен'),state.period==='year'?'21':state.period==='month'?'6':'2',T('Академиялық қозғалыс','Академическое движение'),'chart')}${kpi(T('Жаңа жазылулар','Новые зачисления'),state.period==='year'?'42':state.period==='month'?'12':'3',T('Кезең ішінде','За период'),'users')}</div>${card(T('Қозғалыс түрлері','Виды движения'),`<div class="list-row"><div class="grow"><b>${T('Ротациямен','По ротации')}</b></div><strong>${state.period==='year'?140:state.period==='month'?20:4}</strong></div><div class="list-row"><div class="grow"><b>${T('Деңгей төмендеді','Уровень понижен')}</b></div><strong>1</strong></div>`)}`}
function teacherHome(){return `<div class="kpis">${kpi(T('Менің топтарым','Мои группы'),'2',T('ИС-31 және ИС-32','ИС-31 и ИС-32'),'users')}${kpi(T('Тексеруге','На проверку'),'18',T('Зертханалық жұмыстар','Лабораторные работы'),'file',true)}${kpi(T('Журнал толуы','Заполнение журнала'),'87%',T('Ағымдағы семестр','Текущий семестр'),'book')}</div><div class="grid dashboard"><div class="stack">${card(T('Менің курстарым','Мои занятия'),[['09:00','10:20',T('Алгоритмдер · ИС-31','Алгоритмы · ИС-31'),T('204 ауд. · Дәріс','Ауд. 204 · Лекция')],['10:30','11:50',T('Алгоритмдер · ИС-32','Алгоритмы · ИС-32'),T('204 ауд. · Практика','Ауд. 204 · Практика')]].map(scheduleRow).join(''),goButton('schedule'))}${card(T('Баға журналы','Журнал оценок'),`<p class="muted">${T('Алгоритмдер · ИС-31 · Зертханалық жұмыс №3','Алгоритмы · ИС-31 · Лабораторная работа №3')}</p><a class="btn primary" href="#teacher/journal">${T('Журналды ашу','Открыть журнал')} ${icon('arrow')}</a>`)}</div><div class="stack">${card(T('Қайталау керек тақырыптар','Темы для повторения'),bar(T('Сұрыптау','Сортировка'),61)+bar(T('Рекурсия','Рекурсия'),68)+bar(T('Деректер құрылымы','Структуры данных'),79))}${card(T('ЖИ-көмекші','ИИ-ассистент'),`<p class="muted">${T('Топтың әлсіз тақырыптарын қараңыз немесе демо тест жасаңыз.','Посмотрите слабые темы группы или создайте демо-тест.')}</p><a class="btn" href="#teacher/ai">${T('Көмекшіні ашу','Открыть ассистента')}</a>`)}</div></div>`}
function journal(){return `${card(T('Алгоритмдер · ИС-31','Алгоритмы · ИС-31'),`<p class="subline">${T('Зертханалық жұмыс №3 · 0–100 балл','Лабораторная работа №3 · 0–100 баллов')}</p><form id="journal-form"><div class="data-table-wrap section-gap"><table class="data-table"><thead><tr><th>${T('Студент','Студент')}</th><th>${T('Баға','Оценка')}</th></tr></thead><tbody>${students.slice(0,4).map((s,i)=>`<tr><td><div class="person">${avatar(s.init)}<b>${s.name}</b></div></td><td><input class="grade-input" type="number" min="0" max="100" step="1" name="${s.id}" value="${esc(state.grades[s.id]??[85,78,'',92][i])}" aria-label="${s.name}"></td></tr>`).join('')}</tbody></table></div><button class="btn primary section-gap" type="submit">${icon('check')}${T('Бағаларды сақтау','Сохранить оценки')}</button></form>`)}<p class="notice section-gap">${icon('lock')}${T('Тек өз пәніңіздің журналын өңдейсіз. Демо бағалар осы браузерде сақталады.','Вы редактируете журнал своей дисциплины. Демо-оценки сохраняются в этом браузере.')}</p>`}
function scanner(){return `${card(T('Дерекқор · 3-тест · ИС-31','Базы данных · Тест №3 · ИС-31'),`<div class="notice">${icon('help')}${T('Сканердің демо сценарийі. Бұл нұсқа суреттен жауаптарды анықтамайды.','Демонстрация сценария сканера. Эта версия не распознаёт ответы на изображениях.')}</div><div class="scanner">${icon('scan')}<b>${T('Жауап парағы','Лист ответов')}</b><span>${T('Демо тексеруді іске қосып, нәтижелерді қараңыз','Запустите демо-проверку и посмотрите пример результатов')}</span>${button(T('Демо тексеру','Демо-проверка'),'scan','primary')}</div>${state.scanDone?`<div class="list-row"><div class="grow"><b>Серік Д.</b></div><span class="score good">18 / 20</span></div><div class="list-row"><div class="grow"><b>Әділбекова А.</b></div><span class="score">16 / 20</span></div><div class="list-row"><div class="grow"><b>Бахтияров А.</b></div><span class="score">11 / 20</span></div><div class="section-gap">${button(T('Нәтижелерді сақтау','Сохранить результаты'),'scan-save')}</div>`:''}`)}`}
const contacts={curator:{name:'Жанар Қасымова',init:'ЖҚ',sub:['Топ кураторы','Куратор группы']},teacher:{name:'Асель Нұрғали',init:'АН',sub:['Алгоритмдер оқытушысы','Преподаватель алгоритмов']},database:{name:'Марат Қайрат',init:'МҚ',sub:['Дерекқор оқытушысы','Преподаватель баз данных']},group:{name:'ИС-31',init:'31',sub:['Топ чаты · 24 мүше','Чат группы · 24 участника']}};
function chatKey(){return state.role+'-'+state.contact}
function baseChat(){if(state.contact==='group')return [{mine:false,text:T('Дана (староста): Ертең 10:30 тест. Парақ алып келіңдер.','Дана (староста): Завтра в 10:30 тест. Возьмите листы.')},{mine:false,text:T('Айсана: Рақмет, көрдім!','Айсана: Спасибо, увидела!')}];return [{mine:true,text:T('Қайырлы күн! Консультацияны бейсенбіге ауыстыруға бола ма?','Добрый день! Можно перенести консультацию на четверг?')},{mine:false,text:T('Иә, 15:00-де 311 аудиторияда кездесейік.','Да, встретимся в 15:00 в аудитории 311.')}];}
function bubbles(arr){return arr.map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.text).replace(/\n/g,'<br>')}${m.time?`<small>${esc(m.time)}</small>`:''}</div>`).join('')}
function chats(){if(state.role==='curator')state.contact='group';const c=contacts[state.contact]||contacts.curator;const keys=state.role==='curator'?['group']:['curator','teacher','database','group'];return `<div class="notice">${icon('help')}${T('Демо чат. Хабарламалар тек осы браузерде сақталады, басқа адамдарға жіберілмейді.','Демо-чат. Сообщения сохраняются в этом браузере и не отправляются другим людям.')}</div><div class="chat-layout"><div class="chat-list">${keys.map(k=>`<button class="chat-contact ${state.contact===k?'active':''}" data-action="contact" data-value="${k}">${avatar(contacts[k].init)}<span><b>${contacts[k].name}</b><small>${T(...contacts[k].sub)}</small></span></button>`).join('')}</div><div class="chat-area"><div class="chat-head"><h2>${c.name}</h2><p class="subline">${T(...c.sub)}</p></div><div class="chat-messages" id="chat-messages">${bubbles([...baseChat(),...(state.messages[chatKey()]||[])])}</div><form class="chat-form" id="chat-form"><input name="message" required maxlength="1500" placeholder="${T('Хабарлама жазыңыз…','Напишите сообщение…')}" aria-label="${T('Хабарлама','Сообщение')}"><button class="btn primary" type="submit" aria-label="${T('Жіберу','Отправить')}">${icon('send')}<span>${T('Жіберу','Отправить')}</span></button></form></div></div>`}
function aiSuggestions(){return state.role==='student'?[T('Осы аптада не тапсырамын?','Что сдавать на этой неделе?'),T('Бағаларым қандай?','Какие у меня оценки?'),T('Бүгінгі кесте','Расписание на сегодня')]:state.role==='rector'?[T('Қай факультеттің қатысуы төмен?','У какого факультета низкая посещаемость?'),T('Қаржы есебін көрсет','Покажи финансовую сводку'),T('Қауіптерді көрсет','Покажи риски')]:state.role==='dean'?[T('Қай куратор жауап бермеді?','Какой куратор не ответил?'),T('2 курс үлгерімі','Успеваемость 2 курса'),T('Кімге көмек керек?','Кому нужна помощь?')]:state.role==='curator'?[T('Топтан кімге көмек керек?','Кому в группе нужна помощь?'),T('Кім үздік?','Кто лучший в группе?'),T('Кім тапсырмады?','Кто не сдал задание?')]:[T('Қай тақырыпты қайталау керек?','Какую тему нужно повторить?'),T('Кім тапсырмады?','Кто не сдал задание?'),T('Тест жасау','Создать тест')];}
function aiAnswer(q){const s=q.toLowerCase();const finance=/қаржы|кіріс|финанс|доход|расход/.test(s);if(finance&&state.role!=='rector')return T('Қаржы деректері сіздің демо рөліңізге қолжетімді емес. Мен тек осы рөлге арналған деректермен көмектесемін.','Финансовые данные недоступны вашей демо-роли. Я могу помочь с данными в пределах этой роли.');if(state.role==='student'){if(/баға|оцен|балл/.test(s))return T('Сіздің орташа балыңыз 72.4 / 100. Алгоритмдер: 78, дерекқор: 65, ағылшын тілі: 74. Дерекқор бойынша қателерді оқытушымен талдауды ұсынамын.','Ваш средний балл 72.4 / 100. Алгоритмы: 78, базы данных: 65, английский: 74. Предлагаю разобрать ошибки по базам данных с преподавателем.');if(/кесте|распис|бүгін|сегодня/.test(s))return T('Бүгін: 09:00 алгоритмдер (204), 10:30 дерекқор (311), 12:00 ағылшын тілі (105). Толық кесте «Кесте» бөлімінде.','Сегодня: 09:00 алгоритмы (204), 10:30 базы данных (311), 12:00 английский (105). Подробности в разделе «Расписание».');return T('Осы аптада дерекқор бойынша №3 зертхананы жұмаға дейін тапсыру керек. Алгоритмдер бойынша келесі тапсырма 9 қарашаға дейін. Тапсырмалар бөлімінен аша аласыз.','На этой неделе нужно сдать лабораторную №3 по базам данных до пятницы. Следующее задание по алгоритмам — до 9 ноября. Откройте раздел «Задания».');}if(state.role==='rector')return finance?T('Демо қаржы сводкасы: кіріс 4.2 млрд ₸, шығыс 3.7 млрд ₸, төлем жиналымы 91%. Дерек: «Қаржы», 2026–2027 оқу жылы.','Демо-сводка: доходы 4,2 млрд ₸, расходы 3,7 млрд ₸, собираемость платежей 91%. Источник: «Финансы», 2026–2027 учебный год.'):T('Демо деректер бойынша педагогика факультетінің қатысуы 89%, ИТ факультетінде 96%. Университет бойынша назар аударуды қажет ететін 86 жағдай бар. Кезең: ағымдағы семестр.','По демо-данным посещаемость педагогического факультета — 89%, факультета ИТ — 96%. По университету 86 случаев требуют внимания. Период: текущий семестр.');if(state.role==='dean')return /куратор|жауап|ответ/.test(s)?T('6 жауапсыз сұрау бар: Ерлан Т. — 4, Айдос Б. — 2. «Кураторлар» бөлімінен еске салу әрекетін көрсете аласыз. Бұл демо хабарламаларды жібермейді.','Есть 6 обращений без ответа: Ерлан Т. — 4, Айдос Б. — 2. В разделе «Кураторы» можно показать напоминание. Демо не отправляет сообщения.'):T('ИТ факультеті: орташа балл 74.1, қатысу 96%, академиялық қарызы бар 41 студент. 2 курстың орташа балы 72.8, өткен кезеңнен 0.9 төмен. Дерек: «Үлгерім».','Факультет ИТ: средний балл 74.1, посещаемость 96%, 41 студент с академическими задолженностями. Средний балл 2 курса — 72.8, снижение на 0.9 к прошлому периоду. Источник: «Успеваемость».');if(state.role==='curator')return /үздік|лучш/.test(s)?T('ИС-31 тобында Серік Дана: орташа балл 81.0, қатысу 98%. Қалған нәтижелер «Рейтинг» бөлімінде.','В группе ИС-31 у Серік Даны средний балл 81.0 и посещаемость 98%. Остальные результаты в разделе «Рейтинг».'):T('ИС-31 тобында Бахтияров Алинұрға назар аудару керек: орташа балл 58.7, қатысу 82%, 2 академиялық қарыз. Жеке кездесу ұйымдастыруды ұсынамын. Дерек: «Студенттер».','В группе ИС-31 стоит обратить внимание на Бахтиярова Алинұра: средний балл 58.7, посещаемость 82%, 2 задолженности. Предлагаю организовать личную встречу. Источник: «Студенты».');if(/тест/.test(s))return T('Демо тест үлгісі:\n1. Көпіршікті сұрыптаудың уақыт күрделілігі қандай?\n2. Жылдам сұрыптау қалай жұмыс істейді?\n3. Тұрақты сұрыптау деген не?\nБұл дайын сценарий.','Пример демо-теста:\n1. Какова временная сложность пузырьковой сортировки?\n2. Как работает быстрая сортировка?\n3. Что такое стабильная сортировка?\nЭто подготовленный сценарий.');return T('«Сұрыптау» тақырыбы бойынша орташа балл 61. Практикада осы тақырыпты қайталауды ұсынамын. Бахтияров А. №3 зертхананы әлі тапсырмаған. Дерек: сіздің алгоритмдер курсыңыз.','По теме «Сортировка» средний балл 61. Предлагаю повторить тему на практике. Бахтияров А. ещё не сдал лабораторную №3. Источник: ваш курс алгоритмов.');}
function aiPage(){const arr=state.ai[state.role]||[];return `<div class="ai-layout"><div class="ai-welcome"><div class="ai-mark">${icon('spark')}</div><h2>${T('Сіздің университет көмекшіңіз','Ваш университетский помощник')}</h2><p>${icon('lock')} ${T(...role().scope)}</p></div><div class="notice">${icon('help')}${T('Демо көмекші дайын сценарийлермен жауап береді. Нақты ЖИ сервисі қосылмаған.','Демо-ассистент отвечает по подготовленным сценариям. Сервис ИИ не подключён.')}</div><div class="chat-messages ai-messages" id="ai-messages">${bubbles(arr)}</div><div class="suggestions">${aiSuggestions().map(x=>`<button data-action="ask" data-value="${esc(x)}">${x} ${icon('arrow')}</button>`).join('')}</div><form class="chat-form ai-input" id="ai-form"><input name="question" required maxlength="1000" placeholder="${T('Сұрағыңызды жазыңыз…','Напишите свой вопрос…')}" aria-label="${T('ЖИ-ге сұрақ','Вопрос ассистенту')}"><button class="btn primary" type="submit" aria-label="${T('Сұрау','Спросить')}">${icon('arrow')}</button></form>${arr.length?`<button class="text-link section-gap" data-action="clear-ai">${T('Жаңа әңгіме','Новый разговор')}</button>`:''}</div>`}
function more(){return `<div class="menu-grid">${role().extra.map(k=>`<a class="menu-tile" href="#${state.role}/${k}">${icon(N[k][2])}<span>${label(k)}</span><span class="arrow">${icon('chevron')}</span></a>`).join('')}${button(icon('help')+' '+T('Демо туралы','О демоверсии'),'about','menu-tile')}</div>`}
function logo(){return `<span class="brand-symbol" aria-hidden="true">n<span>·</span>d</span><span class="brand-name">N&D<span>Campus workspace</span></span>`}
function navItem(k){return `<a href="#${state.role}/${k}" class="nav-link ${state.page===k?'active':''}" ${state.page===k?'aria-current="page"':''}>${icon(N[k][2])}<span>${label(k)}</span>${k==='chats'?'<span class="count">3</span>':''}</a>`}
function assistantShortcut(){return `<a class="assistant-shortcut" href="#${state.role}/ai"><span class="assistant-icon">${icon('spark')}</span><span><b>${T('Университет көмекшісі','Университетский ассистент')}</b><small>${T('Кесте, тапсырмалар және нәтижелер','Расписание, задания и результаты')}</small></span>${icon('arrow')}</a>`}
function overviewTrend(){
 const values=state.role==='rector'?[91,94,92,93,94,92,93]:state.role==='dean'?[94,95,94,96,95,97,96]:[93,94,92,94,96,94,95],names=[T('Дс','Пн'),T('Сс','Вт'),T('Ср','Ср'),T('Бс','Чт'),T('Жм','Пт'),T('Сб','Сб'),T('Жс','Вс')];
 const points=values.map((v,i)=>[44+i*85,200-(v-80)/20*170]),line=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
 return `<div class="trend-chart"><svg viewBox="0 0 600 240" role="img" aria-label="${T('Апта бойынша қатысу','Посещаемость по дням недели')}: ${values.join(', ')}%">${[80,90,100].map(v=>`<line x1="42" y1="${200-(v-80)/20*170}" x2="564" y2="${200-(v-80)/20*170}" class="chart-gridline"/><text x="2" y="${204-(v-80)/20*170}">${v}%</text>`).join('')}<path d="${line} L554,200 L44,200Z" class="chart-area"/><path d="${line}" class="chart-line"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${i===6?4:2.5}" class="chart-point"/><text x="${p[0]}" y="229" text-anchor="middle">${names[i]}</text>`).join('')}</svg></div>`;
}
function commandMenu(){const keys=[...new Set([...role().nav,...role().extra])];modal(T('Қай бөлімді ашамыз?','Какой раздел открыть?'),`<div class="command-search">${icon('search')}<input id="command-input" placeholder="${T('Бөлім атауын енгізіңіз…','Введите название раздела…')}" aria-label="${T('Бөлімді іздеу','Поиск раздела')}"><kbd>esc</kbd></div><div class="command-results">${keys.map(k=>`<a class="command-item" href="#${state.role}/${k}" data-command-label="${esc(label(k).toLowerCase())}">${icon(N[k][2])}<span>${label(k)}</span>${icon('arrow')}</a>`).join('')}</div>`);$('#command-input').focus();}
function render(){document.body.dataset.page=state.page;document.body.dataset.role=state.role;document.documentElement.lang=state.lang;document.documentElement.dataset.theme=state.theme;document.title='N&D · '+label(state.page);const pages={home:()=>state.role==='student'?studentHome():staffHome(),schedule,chats,ai:aiPage,more,grades,events:eventPage,points:pointPage,jobs,support,tasks,analytics,finance,ranking,transfers,performance,statistics:analytics,students:studentsPage,curators,journal,scanner};$('#app').innerHTML=shell((pages[state.page]||more)());}
function toast(message){$('#toast').innerHTML=`<div class="toast-box">${esc(message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').innerHTML='',3600)}
let modalReturnFocus;
function modal(title,body){modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="icon-btn close" data-action="close" aria-label="${T('Жабу','Закрыть')}">${icon('close')}</button><h2 id="modal-title">${title}</h2>${body}</section></div>`;$('.modal').focus();}
function closeModal(){$('#modal-root').innerHTML='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus()}
function csv(name,rows){const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){if(state.page==='finance')csv('ND-finance.csv',[[T('Көрсеткіш','Показатель'),T('Мәні','Значение')],[T('Кіріс','Доходы'),'4200000000 KZT'],[T('Шығыс','Расходы'),'3700000000 KZT'],[T('Төлем жиналымы','Собираемость'),'91%']]);else if(state.role==='rector')csv('ND-university.csv',[[T('Көрсеткіш','Показатель'),T('Мәні','Значение')],[T('Студенттер','Студенты'),4120],[T('Орташа балл','Средний балл'),70.8],[T('Қатысу','Посещаемость'),'93.4%']]);else csv('ND-students.csv',[[T('Студент','Студент'),T('Топ','Группа'),T('Орташа балл','Средний балл'),T('Қатысу','Посещаемость')],...filteredStudents().map(s=>[s.name,s.group,s.score,s.att+'%'])]);toast(T('CSV есебі жүктелді','Отчёт CSV скачан'))}
function ask(q){q=q.trim();if(!q)return;const arr=state.ai[state.role]||=[];arr.push({mine:true,text:q},{mine:false,text:aiAnswer(q)});persist();render();$('#ai-messages')?.scrollTo(0,99999)}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,value=el.dataset.value;if(a==='command'){commandMenu();return}if(a==='lang'){state.lang=value;persist();render()}else if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';persist();document.documentElement.dataset.theme=state.theme;render()}else if(a==='period'){state.period=value;render()}else if(a==='filter'){state.filter=value;render()}else if(a==='close')closeModal();else if(a==='about')modal(T('N&D демо нұсқасы','Демоверсия N&D'),`<p>${T('Сіздің макеттеріңіз негізінде жасалған интерактивті университет порталы. Жоғарғы мәзірден рөлді ауыстырып, әр қызметкердің экранын көріңіз.','Интерактивный университетский портал по вашим макетам. Переключайте роли в верхнем меню, чтобы увидеть экраны разных пользователей.')}</p><p>${T('Барлық деректер — мысал. Жазбалар осы браузерде сақталады. Рөлдерді ауыстыру — демонстрация, нақты авторизация емес.','Все данные демонстрационные. Изменения сохраняются в этом браузере. Переключение ролей служит для показа и не является настоящей авторизацией.')}</p>${button(T('Түсінікті','Понятно'),'close')}`);else if(a==='notifications')modal(T('Хабарландырулар','Уведомления'),`<div class="section-gap"><div class="list-row"><span class="task-icon">${icon('calendar')}</span><div class="grow"><b>${T('Welcome Party — 12 қараша','Welcome Party — 12 ноября')}</b><small>${T('Тіркелу ашық','Регистрация открыта')}</small></div></div><div class="list-row"><span class="task-icon">${icon('file')}</span><div class="grow"><b>${T('Зертханалық жұмыс мерзімі','Срок лабораторной работы')}</b><small>${T('Жұмаға дейін','До пятницы')}</small></div></div></div>`);else if(a==='event'){if(state.events.includes(id)){state.events=state.events.filter(x=>x!==id);toast(T('Жазылу тоқтатылды','Запись отменена'))}else{state.events.push(id);toast(T('Демо жазылу сақталды. Поинттер қосылды!','Демо-запись сохранена. Поинты добавлены!'))}persist();render()}else if(a==='job'){if(!state.applications.includes(id)){modal(T('Өтінім беру','Отклик на вакансию'),`<p>${T('Өтінім демо нұсқада сақталады. Жұмыс берушіге жіберілмейді.','Заявка сохранится в демоверсии и не будет отправлена работодателю.')}</p><form id="job-form" data-id="${id}"><label>${T('Неге бұл жұмыс қызықты?','Почему вам интересна эта работа?')}</label><textarea name="motivation" required maxlength="1500"></textarea><button class="btn primary" type="submit">${T('Демо өтінімді сақтау','Сохранить демо-заявку')}</button></form>`)}}else if(a==='book'){if(!state.bookings.includes(id)){state.bookings.push(id);persist();render();toast(T('Демо жазылу сақталды','Демо-запись сохранена'))}else toast(T('Сіз бұл уақытқа жазылдыңыз','Вы уже выбрали это время'))}else if(a==='task')modal(T('Тапсырма','Задание'),`<p>${id==='db'?T('№3 зертхана: SQL сұрауларын құру. Нәтижесін файл ретінде қосыңыз.','Лабораторная №3: составление SQL-запросов. Прикрепите файл с результатом.'):T('Сұрыптау алгоритмін іске асырып, күрделілігін түсіндіріңіз.','Реализуйте алгоритм сортировки и объясните его сложность.')}</p><form id="task-form" data-id="${id}"><label>${T('Жұмыс файлы','Файл работы')}</label><input name="attachment" type="file" required><p>${T('Файл серверге жіберілмейді. Демода тек тапсырылғаны туралы белгі сақталады.','Файл не отправляется на сервер. В демо сохраняется только отметка о сдаче.')}</p><button class="btn primary" type="submit">${T('Тапсырылды деп белгілеу','Отметить как сданное')}</button></form>`);else if(a==='student'){const s=students.find(s=>s.id===Number(id));if(s&&(state.role!=='curator'||s.group==='ИС-31'))modal(s.name,`<p>${s.group} · ${s.course} ${T('курс','курс')} · ${T('ИТ факультеті','Факультет ИТ')}</p><div class="list-row"><span>${T('Орташа балл','Средний балл')}</span>${score(s.score)}</div><div class="list-row"><span>${T('Қатысу','Посещаемость')}</span><b>${s.att}%</b></div><div class="list-row"><span>${T('Академиялық қарыз','Задолженности')}</span><b>${s.debt}</b></div><p>${T('Көрсетілген ақпарат — демонстрациялық мысал.','Показанная информация — демонстрационный пример.')}</p>`)}else if(a==='contact'){state.contact=value;render()}else if(a==='ask')ask(value);else if(a==='clear-ai'){state.ai[state.role]=[];persist();render()}else if(a==='export')exportData();else if(a==='schedule-export'){csv('ND-schedule.csv',[[T('Басталуы','Начало'),T('Аяқталуы','Конец'),T('Пән','Дисциплина'),T('Аудитория','Аудитория')],...scheduleRows()]);toast(T('Кесте жүктелді','Расписание скачано'))}else if(a==='reminders'||a==='reminder-one')modal(T('Демо еске салу','Демо-напоминание'),`<p>${a==='reminder-one'?esc(el.dataset.name):T('Ерлан Т. — 4 сұрау, Айдос Б. — 2 сұрау.','Ерлан Т. — 4 обращения, Айдос Б. — 2 обращения.')}</p><p>${T('Мәтін үлгісі: «Студенттердің жауапсыз сұрауларына жауап беруді сұраймыз». Бұл демонстрацияда хабарлама жіберілмейді.','Пример текста: «Просим ответить на открытые обращения студентов». В демонстрации сообщение не отправляется.')}</p>${button(T('Түсінікті','Понятно'),'close')}`);else if(a==='show-risks')navigate(state.role==='rector'?'analytics':'students');else if(a==='add-group')modal(T('Топ қосу','Добавить группу'),`<form id="group-form"><label>${T('Топ атауы','Название группы')}</label><input name="group" required maxlength="20" placeholder="ИС-51"><label>${T('Куратор','Куратор')}</label><input name="curator" required maxlength="50"><button type="submit" class="btn primary">${T('Сақтау','Сохранить')}</button></form>`);else if(a==='scan'){state.scanDone=true;render();toast(T('Демо тексеру аяқталды','Демо-проверка завершена'))}else if(a==='scan-save'){state.scanSaved=true;persist();toast(T('Демо нәтижелер сақталды','Демо-результаты сохранены'))}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){state.role=e.target.value;state.contact='curator';persist();location.hash=`${state.role}/home`;updateRoute()}if(e.target.id==='course-filter'){state.filter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='command-input'){const q=e.target.value.toLowerCase();document.querySelectorAll('.command-item').forEach(a=>a.hidden=!a.dataset.commandLabel.includes(q))}if(e.target.id==='student-search'){state.query=e.target.value;$('#students-body').innerHTML=studentTableBody()}});
document.addEventListener('submit',e=>{const f=e.target;if(!['chat-form','ai-form','journal-form','group-form','job-form','task-form'].includes(f.id))return;e.preventDefault();const d=new FormData(f);if(f.id==='chat-form'){const message=String(d.get('message')||'').trim();if(!message)return;(state.messages[chatKey()]||=[]).push({mine:true,text:message,time:new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'})});persist();render();$('#chat-messages').scrollTop=99999;$('#chat-form input').focus()}else if(f.id==='ai-form')ask(String(d.get('question')));else if(f.id==='journal-form'){for(const [id,n]of d){if(n!==''&&(Number(n)<0||Number(n)>100)){toast(T('Баға 0–100 аралығында болуы керек','Оценка должна быть от 0 до 100'));return}state.grades[id]=n===''?'':Number(n)}persist();toast(T('Демо бағалар сақталды','Демо-оценки сохранены'))}else if(f.id==='group-form'){(state.groups||=[]).push([String(d.get('curator')).trim(),String(d.get('group')).trim(),0,0]);persist();closeModal();render();toast(T('Демо топ қосылды','Демо-группа добавлена'))}else if(f.id==='job-form'){state.applications.push(f.dataset.id);persist();closeModal();render();toast(T('Демо өтінім сақталды','Демо-заявка сохранена'))}else if(f.id==='task-form'){if(!state.submitted.includes(f.dataset.id))state.submitted.push(f.dataset.id);persist();closeModal();render();toast(T('Тапсырма белгіленді','Задание отмечено как сданное'))}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandMenu();return}if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...$('.modal').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled);const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('click',e=>{if(e.target.closest('.command-item'))closeModal()});
window.addEventListener('hashchange',updateRoute);updateRoute();
